def area(rect):
    x1,y1,x2,y2 = rect
    if x1 > x2 or y1 > y2:
        raise ValueError("inverted rectangle")
    return (x2-x1)*(y2-y1)
def intersection(a,b):
    return max(0,min(a[2],b[2])-max(a[0],b[0])) * max(0,min(a[3],b[3])-max(a[1],b[1]))

